export const money=v=>Number.isFinite(v)?new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:2}).format(v):'—';
export const pct=v=>Number.isFinite(v)?`${v>=0?'+':''}${(v*100).toFixed(2)}%`:'—';
export const stamp=v=>v?new Date(v).toLocaleString('en-CA',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function selectRange(points,range,now=Date.now()) {const hours={ '1D':24,'1W':168,'1M':720 };return points.filter(p=>Number.isFinite(p.time)&&(!hours[range]||p.time>=now-hours[range]*3600000));}
export function chartGeometry(series){const all=series.flatMap(s=>s.points.filter(p=>Number.isFinite(p.value)&&Number.isFinite(p.time)));if(!all.length)return null;const start=Math.min(...all.map(p=>p.time)),end=Math.max(...all.map(p=>p.time));let low=Math.min(...all.map(p=>p.value)),high=Math.max(...all.map(p=>p.value));const pad=Math.max((high-low)*.18,Math.abs(high)*.002,0.01);low-=pad;high+=pad;return {start,end,low,high,x:t=>16+(t-start)/Math.max(1,end-start)*864,y:v=>224-(v-low)/(high-low)*194};}
const chartMoney=(value,currency='CAD')=>Number.isFinite(value)?new Intl.NumberFormat('en-CA',{style:'currency',currency,maximumFractionDigits:2}).format(value):'—';
export function chartHTML(series,{label='Historical chart',volume=false}={}){
 const g=chartGeometry(series);if(!g)return '<div class="chart-empty"><span>⌁</span><h3>No observations in this period</h3><p>Choose a wider timeframe or wait for the next recorded update.</p></div>';
 const guides=Array.from({length:5},(_,i)=>{const y=30+i*48.5,v=g.high-i*(g.high-g.low)/4;return `<path d="M16 ${y}H880" class="gridline"/><text x="900" y="${y+4}" class="axis">${v.toFixed(2)}</text>`}).join('');
 const plots=series.map((s,i)=>{let segments=[],current=[];for(const p of s.points){if(Number.isFinite(p.value)){current.push(p)}else if(current.length){segments.push(current);current=[]}}if(current.length)segments.push(current);return segments.map(points=>{const path=points.map((p,j)=>`${j?'L':'M'}${g.x(p.time).toFixed(2)},${g.y(p.value).toFixed(2)}`).join(' ');return `${i===0&&points.length>1?`<path d="${path}L${g.x(points.at(-1).time)} 235L${g.x(points[0].time)} 235Z" fill="url(#chart-fill)"/>`:''}<path d="${path}" stroke="${s.color}" fill="none" stroke-width="2" vector-effect="non-scaling-stroke"/>${points.length===1?`<circle cx="${g.x(points[0].time)}" cy="${g.y(points[0].value)}" r="4" fill="${s.color}"/>`:''}`}).join('')}).join('');
 const ps=series[0].points,volMax=Math.max(1,...ps.map(p=>p.volume||0));const volumes=volume?ps.map(p=>`<rect x="${g.x(p.time)}" y="${284-(p.volume||0)/volMax*35}" width="${Math.max(1,Math.min(8,850/ps.length-1))}" height="${(p.volume||0)/volMax*35}" fill="#2b6058"/>`).join(''):'';
 return `<div class="chart" data-chart><div class="chart-readout" aria-live="off">${esc(series[0].name)} · ${stamp(ps.at(-1)?.time)} <strong>${chartMoney(ps.at(-1)?.value,series[0].currency)}</strong></div><svg viewBox="0 0 984 ${volume?326:272}" role="img" aria-label="${esc(label)}"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#65ebc5" stop-opacity=".14"/><stop offset="1" stop-color="#65ebc5" stop-opacity="0"/></linearGradient></defs>${guides}${plots}${volumes}<text x="16" y="${volume?310:262}" class="axis">${stamp(g.start)}</text><text x="880" y="${volume?310:262}" text-anchor="end" class="axis">${stamp(g.end)}</text><line class="crosshair" x1="16" x2="16" y1="20" y2="235" visibility="hidden"/></svg><input class="chart-scrubber" type="range" min="0" max="${Math.max(0,ps.length-1)}" value="${Math.max(0,ps.length-1)}" aria-label="Inspect historical chart observations"><div class="chart-hint">Drag to inspect ${volume?'· Hourly base-asset volume below':''}</div></div>`;
}
export function bindChart(root,series){const el=root.querySelector('[data-chart]');if(!el)return;const points=series[0].points,g=chartGeometry(series),slider=el.querySelector('input'),svg=el.querySelector('svg');const inspect=index=>{const p=points[index];if(!p)return;slider.value=index;slider.setAttribute('aria-valuetext',`${stamp(p.time)}, ${chartMoney(p.value,series[0].currency)}`);el.querySelector('.chart-readout').innerHTML=`${stamp(p.time)} ${series.map(s=>{const value=s.points.find(v=>v.time===p.time)?.value;return `<span style="color:${s.color}">${esc(s.name)} <strong>${chartMoney(value,s.currency)}</strong></span>`}).join(' ')}`;const line=el.querySelector('.crosshair');line.setAttribute('x1',g.x(p.time));line.setAttribute('x2',g.x(p.time));line.setAttribute('visibility','visible')};slider.oninput=()=>inspect(Number(slider.value));svg.onpointermove=e=>{const rect=svg.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*984,t=g.start+(x-16)/864*(g.end-g.start);let closest=0;points.forEach((p,i)=>{if(Math.abs(p.time-t)<Math.abs(points[closest].time-t))closest=i});inspect(closest)};}
